using System.IO.Compression;
using System.Text;
using System.Xml;
using Pos.Application;

namespace PosFlutter.Web.Services;

/// <summary>Dependency-free, bounded report writers. Text is neutralized before spreadsheet serialization.</summary>
public static class ReportExportWriter
{
    private static readonly string[] Headers=["Folio","Fecha","Vendedor","Pago","Estado","Unidades","Importe","Costo FIFO","Utilidad FIFO"];
    private static string Safe(string? value) { var s=(value??"").Replace("\r"," ").Replace("\n"," ").Trim(); return s.Length>0 && "=+-@".Contains(s[0]) ? "'"+s : s; }
    private static IEnumerable<string[]> Rows(IReadOnlyList<SaleReportDetailRow> rows) => rows.Select(x => new[]{Safe(x.Folio),x.SaleDateTime.ToString("yyyy-MM-dd HH:mm"),Safe(x.UserName),Safe(x.PaymentMethod),Safe(x.Status),x.Units.ToString(),(x.TotalCents/100m).ToString("0.00"),(x.FifoCostCents/100m).ToString("0.00"),(x.GrossProfitCents/100m).ToString("0.00")});
    public static byte[] Write(string format,IReadOnlyList<SaleReportDetailRow> rows,ReportPeriod period) => format.ToLowerInvariant() switch { "csv"=>Csv(rows), "xlsx"=>Xlsx(rows), "pdf"=>Pdf(rows,period), _=>throw new ArgumentException("Unsupported export format.") };
    private static byte[] Csv(IReadOnlyList<SaleReportDetailRow> rows) { var b=new StringBuilder(); void L(IEnumerable<string> r)=>b.AppendLine(string.Join(",",r.Select(x=>"\""+x.Replace("\"","\"\"")+"\""))); L(Headers); foreach(var r in Rows(rows))L(r); return new UTF8Encoding(true).GetBytes(b.ToString()); }
    private static string Xml(string value) => System.Security.SecurityElement.Escape(value) ?? "";
    private static byte[] Xlsx(IReadOnlyList<SaleReportDetailRow> rows) { using var ms=new MemoryStream(); using(var z=new ZipArchive(ms,ZipArchiveMode.Create,true)) { void E(string n,string s){using var w=new StreamWriter(z.CreateEntry(n).Open(),new UTF8Encoding(false));w.Write(s);} E("[Content_Types].xml","<?xml version=\"1.0\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>"); E("_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>"); E("xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Ventas\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>"); E("xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>"); var all=new[]{Headers}.Concat(Rows(rows)); var sheet="<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>"+string.Concat(all.Select((r,i)=>"<row r=\""+(i+1)+"\">"+string.Concat(r.Select(v=>"<c t=\"inlineStr\"><is><t>"+Xml(v)+"</t></is></c>"))+"</row>"))+"</sheetData></worksheet>"; E("xl/worksheets/sheet1.xml",sheet); } return ms.ToArray(); }
    private static byte[] Pdf(IReadOnlyList<SaleReportDetailRow> rows,ReportPeriod period) { var lines=new List<string>{"Reporte de ventas autorizado",$"Periodo: {period.From:yyyy-MM-dd} a {period.ToExclusive:yyyy-MM-dd}",string.Join(" | ",Headers)}; lines.AddRange(Rows(rows).Select(r=>string.Join(" | ",r))); var content="BT /F1 8 Tf 40 800 Td "+string.Join(" Tj 0 -14 Td ",lines.Take(48).Select(x=>"("+x.Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)")+")"))+" Tj ET"; var objects=new[]{"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>","<< /Length "+Encoding.ASCII.GetByteCount(content)+" >>\nstream\n"+content+"\nendstream"}; var sb=new StringBuilder("%PDF-1.4\n"); var offsets=new List<int>{0}; for(var i=0;i<objects.Length;i++){offsets.Add(Encoding.ASCII.GetByteCount(sb.ToString()));sb.Append($"{i+1} 0 obj\n{objects[i]}\nendobj\n");}var x=Encoding.ASCII.GetByteCount(sb.ToString());sb.Append("xref\n0 6\n0000000000 65535 f \n");foreach(var o in offsets.Skip(1))sb.Append(o.ToString("D10")+" 00000 n \n");sb.Append($"trailer << /Size 6 /Root 1 0 R >>\nstartxref\n{x}\n%%EOF");return Encoding.ASCII.GetBytes(sb.ToString()); }
}
